const input = $input.first().json;
const requested = (
  String(input.requested_service || '') + ' ' +
  String(input.chatInput || '') + ' ' +
  String(input.customer_message || '') + ' ' +
  String(input.business_need || '')
).toLowerCase().trim();

const isCloseWon = /finalize.*contract|close.*deal|approved.*proposal|management.*approved|proposal.*approved|ready to sign|sign.*contract|sign.*agreement|proceed.*with.*contract|move forward with.*(closing|the deal|contract)|contract finalization|accept.*(quote|proposal)|approved.*quote|finalize.*sow|sign.*sow|close_won/i.test(requested);

if (isCloseWon) {
  return [{
    json: {
      ...input,
      fit: true,
      fit_reason: 'Deal closure and contract finalization approved. Service qualification and pricing validation bypassed.',
      is_close_won: true
    }
  }];
}

let dnaServices = '';
try {
  const dna = $('Get Company DNA').first()?.json;
  dnaServices = String(dna?.services || '').toLowerCase();
} catch (e) {}

const coreKeywords = [
  'penetration testing', 'pentest', 'red team', 'adversary simulation',
  'security audit', 'security auditing', 'vulnerability', 'assessment',
  'cloud security', 'cloud security assessment', 'incident response',
  'ransomware', 'soc', 'compliance', 'iso', 'soc 2', 'pci',
  'pricing', 'price', 'package', 'tier', 'sales', 'enterprise',
  'license', 'licensing', 'quote', 'proposal', 'sow', 'cost',
  'commercial', 'service', 'audit', 'defense'
];

const dnaKeywords = dnaServices ? dnaServices.split(',').map(s => s.trim().toLowerCase()).filter(Boolean) : [];
const allKeywords = [...new Set([...coreKeywords, ...dnaKeywords])];

const fit = !requested || allKeywords.some(kw => requested.includes(kw));

return [{
  json: {
    ...input,
    fit: fit,
    fit_reason: fit
      ? 'Requested inquiry aligns with company cybersecurity services & commercial capabilities.'
      : 'Requested service is outside our current cybersecurity capabilities.'
  }
}];

